import {
  AnimatePresence,
  type AnimationPlaybackControls,
  animate,
  motion,
  useMotionValue,
  useMotionValueEvent,
  useReducedMotion,
  useTransform,
  type Variants,
} from "motion/react";
import {
  type KeyboardEvent,
  type PointerEvent,
  useEffect,
  useId,
  useRef,
  useState,
} from "react";
import { cn } from "./utils";

// The dial sweeps 270°, from 7:30 to 4:30 on a clock face.
const SWEEP = 270;
const START_ANGLE = -135;
// How far (deg) the knob can be wound past either end. The pull flattens
// out as it approaches this, so it slows down instead of hitting a wall.
const MAX_OVERSHOOT = 16;
// While dragging, the knob is pulled this much toward the nearest notch,
// which is what makes it feel like it clicks from one step to the next.
const DETENT_PULL = 0.65;
const MAX_TICKS = 56;
// The swell that follows the indicator round the ring: extra length (px)
// at its peak, and how many degrees it spreads either side.
const WAVE_HEIGHT = 9;
const WAVE_WIDTH = 12;
// Pointer movement this close to the centre gives wild angle jumps.
const DEAD_ZONE = 14;
// Below this speed (fraction of the range per second) a release just
// settles into the nearest notch instead of coasting.
const FLICK_THRESHOLD = 0.4;
const VELOCITY_WINDOW_MS = 80;
// Seconds of travel a flick is worth: release speed × COAST = distance coasted.
const COAST = 0.3;
const SETTLE_SPRING = { type: "spring", duration: 0.35, bounce: 0.2 } as const;
const EASE_OUT = [0.23, 1, 0.32, 1] as const;

function damp(distance: number, max: number) {
  return max * (1 - Math.exp(-distance / max));
}

function clamp(value: number, min: number, max: number) {
  return Math.min(Math.max(value, min), max);
}

function snap(value: number, min: number, step: number) {
  return Number((Math.round((value - min) / step) * step + min).toFixed(10));
}

function polar(cx: number, cy: number, radius: number, angle: number) {
  const rad = (angle * Math.PI) / 180;
  // Rounded so the server and the browser, whose trig can differ in the
  // last digits, render identical markup.
  return {
    x: Math.round((cx + radius * Math.sin(rad)) * 100) / 100,
    y: Math.round((cy - radius * Math.cos(rad)) * 100) / 100,
  };
}

function pointerAngle(event: PointerEvent, rect: DOMRect) {
  const dx = event.clientX - (rect.left + rect.width / 2);
  const dy = event.clientY - (rect.top + rect.height / 2);
  return {
    angle: (Math.atan2(dx, -dy) * 180) / Math.PI,
    distance: Math.hypot(dx, dy),
  };
}

// navigator.vibrate is a no-op where unsupported (iOS, desktop). On
// Android it gives each notch a faint tick under the finger.
function hapticTick() {
  if (typeof navigator !== "undefined" && "vibrate" in navigator) {
    navigator.vibrate(1);
  }
}

export interface DetentDialProps {
  /** Accessible name, also shown inside the knob. */
  label?: string;
  min?: number;
  max?: number;
  step?: number;
  /** Initial value when uncontrolled. Double-clicking the knob returns here. */
  defaultValue?: number;
  /** Controlled value. */
  value?: number;
  onValueChange?: (value: number) => void;
  /** Formats the readout, the end labels and `aria-valuetext`. */
  formatValue?: (value: number) => string;
  /** Diameter in px. */
  size?: number;
  disabled?: boolean;
  className?: string;
}

export default function DetentDial({
  label = "Temperature",
  min = 16,
  max = 30,
  step = 0.5,
  defaultValue = 21,
  value: valueProp,
  onValueChange,
  formatValue = (v) => `${v.toFixed(1)}°`,
  size = 240,
  disabled = false,
  className,
}: DetentDialProps) {
  const labelId = useId();
  const knobRef = useRef<HTMLDivElement>(null);
  const tickRefs = useRef<(SVGLineElement | null)[]>([]);
  // The length last written to each tick, so a frame only touches the few
  // ticks the swell is actually passing over.
  const tickLengths = useRef<number[]>([]);
  const reduceMotion = useReducedMotion();
  const range = max - min;

  const initial = clamp(valueProp ?? defaultValue, min, max);
  const [value, setValue] = useState(initial);
  const [direction, setDirection] = useState<1 | -1>(1);
  const [grabbing, setGrabbing] = useState(false);
  const committed = useRef(initial);
  const pointerType = useRef("mouse");

  // The raw, unsnapped position in value units. It can run past min/max
  // while winding; everything visual is derived from it.
  const raw = useMotionValue(initial);
  const animation = useRef<AnimationPlaybackControls | null>(null);
  const drag = useRef<{
    id: number;
    // Measured once on grab: reading layout on every move forces the
    // browser to recalculate it after each frame's writes.
    rect: DOMRect;
    lastAngle: number;
    samples: { t: number; v: number }[];
  } | null>(null);

  const rotation = useTransform(raw, (r) => {
    const degPerUnit = range === 0 ? 0 : SWEEP / range;
    if (r < min) {
      return START_ANGLE - damp((min - r) * degPerUnit, MAX_OVERSHOOT);
    }
    if (r > max) {
      return START_ANGLE + SWEEP + damp((r - max) * degPerUnit, MAX_OVERSHOOT);
    }
    const notch = snap(r, min, step);
    const pulled = notch + (r - notch) * (1 - DETENT_PULL);
    return START_ANGLE + (pulled - min) * degPerUnit;
  });

  // Only re-render when the dial crosses into a new notch, not per frame.
  useMotionValueEvent(raw, "change", (r) => {
    const next = clamp(snap(r, min, step), min, max);
    if (next === committed.current) {
      return;
    }
    setDirection(next > committed.current ? 1 : -1);
    committed.current = next;
    setValue(next);
    onValueChange?.(next);
    if (pointerType.current === "touch") {
      hapticTick();
    }
  });

  // Follow a controlled value when the parent changes it.
  useEffect(() => {
    if (valueProp === undefined || drag.current) {
      return;
    }
    const next = clamp(valueProp, min, max);
    if (next !== committed.current) {
      animation.current?.stop();
      committed.current = next;
      setValue(next);
      raw.jump(next);
    }
  }, [valueProp, min, max, raw]);

  useEffect(() => () => animation.current?.stop(), []);

  const settleTo = (target: number) => {
    animation.current?.stop();
    animation.current = animate(
      raw,
      target,
      reduceMotion ? { duration: 0 } : SETTLE_SPRING
    );
  };

  // Keyboard and wheel steps jump straight to the value. They repeat fast,
  // and an animation on each would trail behind the input.
  const stepBy = (delta: number) => {
    animation.current?.stop();
    const target = clamp(snap(committed.current + delta, min, step), min, max);
    pointerType.current = "keyboard";
    raw.jump(target);
  };

  const handlePointerDown = (event: PointerEvent<HTMLDivElement>) => {
    if (disabled || drag.current) {
      return;
    }
    if (event.pointerType === "mouse" && event.button !== 0) {
      return;
    }
    const rect = event.currentTarget.getBoundingClientRect();
    const { angle } = pointerAngle(event, rect);
    animation.current?.stop();
    pointerType.current = event.pointerType;
    event.currentTarget.setPointerCapture(event.pointerId);
    drag.current = {
      id: event.pointerId,
      rect,
      lastAngle: angle,
      samples: [{ t: event.timeStamp, v: raw.get() }],
    };
    setGrabbing(true);
  };

  const handlePointerMove = (event: PointerEvent<HTMLDivElement>) => {
    const current = drag.current;
    if (!current || current.id !== event.pointerId) {
      return;
    }
    const { angle, distance } = pointerAngle(event, current.rect);
    if (distance < DEAD_ZONE) {
      current.lastAngle = angle;
      return;
    }
    // Unwrap so crossing 6 o'clock doesn't read as a 360° jump.
    let delta = angle - current.lastAngle;
    if (delta > 180) {
      delta -= 360;
    } else if (delta < -180) {
      delta += 360;
    }
    current.lastAngle = angle;
    const next = raw.get() + (delta / SWEEP) * range;
    raw.set(next);
    current.samples.push({ t: event.timeStamp, v: next });
    while (
      current.samples.length > 2 &&
      event.timeStamp - current.samples[0].t > VELOCITY_WINDOW_MS
    ) {
      current.samples.shift();
    }
  };

  const handlePointerUp = (event: PointerEvent<HTMLDivElement>) => {
    const current = drag.current;
    if (!current || current.id !== event.pointerId) {
      return;
    }
    drag.current = null;
    setGrabbing(false);

    const first = current.samples[0];
    const last = current.samples.at(-1) ?? first;
    const elapsed = (last.t - first.t) / 1000;
    // Holding still before letting go is a placement, not a flick.
    const paused = event.timeStamp - last.t > VELOCITY_WINDOW_MS;
    const velocity = elapsed > 0 && !paused ? (last.v - first.v) / elapsed : 0;
    const position = raw.get();
    const inBounds = position >= min && position <= max;

    if (
      reduceMotion ||
      !inBounds ||
      Math.abs(velocity) < range * FLICK_THRESHOLD
    ) {
      settleTo(clamp(snap(position, min, step), min, max));
      return;
    }
    // A flick coasts, slows down, and lands on a notch. If it runs out of
    // room it bounces off the end instead of stopping dead.
    animation.current?.stop();
    // Project where the flick would coast to, land that on a notch, then
    // spring there carrying the release velocity. If the projection runs
    // past an end, the spring overshoots it a little and settles back.
    const target = clamp(
      snap(position + velocity * COAST, min, step),
      min,
      max
    );
    animation.current = animate(raw, target, {
      type: "spring",
      velocity,
      stiffness: 140,
      damping: 24,
      restDelta: 0.005,
    });
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (disabled) {
      return;
    }
    const big = Math.max(step, snap(range / 10, 0, step));
    const keySteps: Record<string, number> = {
      ArrowUp: step,
      ArrowRight: step,
      ArrowDown: -step,
      ArrowLeft: -step,
      PageUp: big,
      PageDown: -big,
      Home: min - committed.current,
      End: max - committed.current,
    };
    if (!(event.key in keySteps)) {
      return;
    }
    event.preventDefault();
    stepBy(keySteps[event.key]);
  };

  // The wheel only turns the dial once it has focus, so scrolling the page
  // past it never changes the value by accident. The listener is attached
  // once and reads the latest props through a ref.
  const wheelStep = useRef({ disabled, step, stepBy });
  wheelStep.current = { disabled, step, stepBy };
  useEffect(() => {
    const knob = knobRef.current;
    if (!knob) {
      return;
    }
    let accumulated = 0;
    const onWheel = (event: WheelEvent) => {
      const latest = wheelStep.current;
      if (latest.disabled || document.activeElement !== knob) {
        return;
      }
      event.preventDefault();
      accumulated += event.deltaY;
      // Trackpads send many tiny deltas; one notch per ~40px of scroll.
      while (Math.abs(accumulated) >= 40) {
        const sign = Math.sign(accumulated);
        accumulated -= sign * 40;
        latest.stepBy(-sign * latest.step);
      }
    };
    knob.addEventListener("wheel", onWheel, { passive: false });
    return () => knob.removeEventListener("wheel", onWheel);
  }, []);

  const center = size / 2;
  const tickCount = Math.max(1, Math.min(Math.round(range / step), MAX_TICKS));
  const valueFraction = range === 0 ? 0 : (value - min) / range;
  const activeTick = Math.round(valueFraction * tickCount);
  const knobSize = size * 0.64;
  const outer = size / 2 - 6;

  // Ticks swell as the indicator passes them, following its exact angle
  // (not the snapped value), so a wave travels round the ring as you turn.
  function tickLength(i: number, indicatorAngle: number) {
    const angle = START_ANGLE + (i / tickCount) * SWEEP;
    // Min, mid and max read as the scale's anchors, like a ruler's inch marks.
    const anchor = i === 0 || i === tickCount || i * 2 === tickCount;
    const major = i % 5 === 0;
    let base = 6;
    if (anchor) {
      base = 14;
    } else if (major) {
      base = 10;
    }
    const distance = (angle - indicatorAngle) / WAVE_WIDTH;
    // Rounded to a tenth of a pixel: finer changes aren't visible, and
    // skipping them leaves most ticks untouched on any given frame.
    return (
      Math.round((base + WAVE_HEIGHT * Math.exp(-distance * distance)) * 10) /
      10
    );
  }

  function tickGeometry(i: number, length: number) {
    const angle = START_ANGLE + (i / tickCount) * SWEEP;
    return {
      a: polar(center, center, outer - length, angle),
      b: polar(center, center, outer, angle),
    };
  }

  // Written straight to the lines each frame; no re-render while turning.
  useMotionValueEvent(rotation, "change", (indicatorAngle) => {
    for (let i = 0; i <= tickCount; i++) {
      const line = tickRefs.current[i];
      const length = tickLength(i, indicatorAngle);
      if (!line || tickLengths.current[i] === length) {
        continue;
      }
      tickLengths.current[i] = length;
      const { a } = tickGeometry(i, length);
      line.setAttribute("x1", String(a.x));
      line.setAttribute("y1", String(a.y));
    }
  });
  const minLabel = polar(center, center, outer + 2, START_ANGLE - 12);
  const maxLabel = polar(center, center, outer + 2, START_ANGLE + SWEEP + 12);

  return (
    <div
      className={cn(
        "relative select-none",
        disabled && "opacity-50",
        className
      )}
      style={{ width: size, height: size }}
    >
      <svg
        aria-hidden="true"
        className="absolute inset-0"
        height={size}
        viewBox={`0 0 ${size} ${size}`}
        width={size}
      >
        {Array.from({ length: tickCount + 1 }, (_, i) => {
          const lit = i <= activeTick;
          const current = i === activeTick;
          const length = tickLength(i, rotation.get());
          tickLengths.current[i] = length;
          const { a, b } = tickGeometry(i, length);
          return (
            <line
              className={cn(
                "transition-[stroke] duration-150",
                current && "stroke-orange-600 dark:stroke-orange-400",
                !current &&
                  (lit
                    ? "stroke-zinc-900 dark:stroke-zinc-100"
                    : "stroke-zinc-300 dark:stroke-zinc-700")
              )}
              // biome-ignore lint/suspicious/noArrayIndexKey: ticks are positional.
              key={i}
              ref={(node) => {
                tickRefs.current[i] = node;
              }}
              strokeLinecap="round"
              strokeWidth={current ? 2 : 1.5}
              x1={a.x}
              x2={b.x}
              y1={a.y}
              y2={b.y}
            />
          );
        })}
      </svg>

      <span
        aria-hidden="true"
        className="absolute -translate-x-1/2 text-[11px] text-zinc-400 tabular-nums"
        style={{ left: minLabel.x, top: minLabel.y }}
      >
        {formatValue(min)}
      </span>
      <span
        aria-hidden="true"
        className="absolute -translate-x-1/2 text-[11px] text-zinc-400 tabular-nums"
        style={{ left: maxLabel.x, top: maxLabel.y }}
      >
        {formatValue(max)}
      </span>

      <div
        aria-disabled={disabled || undefined}
        aria-labelledby={labelId}
        aria-valuemax={max}
        aria-valuemin={min}
        aria-valuenow={value}
        aria-valuetext={formatValue(value)}
        className={cn(
          "absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 touch-none rounded-full outline-none",
          "border border-zinc-200 bg-white shadow-[0_1px_2px_rgb(0_0_0/0.06),0_12px_32px_-12px_rgb(0_0_0/0.25)] dark:border-zinc-800 dark:bg-zinc-900 dark:shadow-[0_1px_2px_rgb(0_0_0/0.4),0_12px_32px_-12px_rgb(0_0_0/0.8)]",
          "transition-[border-color] duration-150 focus-visible:ring-2 focus-visible:ring-zinc-400 focus-visible:ring-offset-4 focus-visible:ring-offset-white dark:focus-visible:ring-offset-zinc-950",
          grabbing
            ? "cursor-grabbing border-zinc-300 dark:border-zinc-700"
            : "cursor-grab",
          disabled && "cursor-not-allowed"
        )}
        onDoubleClick={() => {
          if (!disabled) {
            pointerType.current = "mouse";
            settleTo(clamp(defaultValue, min, max));
          }
        }}
        onKeyDown={handleKeyDown}
        onLostPointerCapture={handlePointerUp}
        onPointerCancel={handlePointerUp}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        ref={knobRef}
        role="slider"
        style={{ width: knobSize, height: knobSize }}
        tabIndex={disabled ? -1 : 0}
      >
        {/* Only the indicator turns; the readout stays upright. */}
        <motion.div
          aria-hidden="true"
          className="absolute inset-0"
          style={{ rotate: rotation }}
        >
          <span className="absolute top-2.5 left-1/2 h-3 w-[3px] -translate-x-1/2 rounded-full bg-zinc-900 dark:bg-zinc-100" />
        </motion.div>

        <div className="pointer-events-none absolute inset-0 flex flex-col items-center justify-center">
          <span
            className="text-xs text-zinc-500 dark:text-zinc-400"
            id={labelId}
          >
            {label}
          </span>
          <RollingValue
            direction={direction}
            reduceMotion={Boolean(reduceMotion)}
            text={formatValue(value)}
          />
        </div>
      </div>
    </div>
  );
}

/**
 * Each character rolls on its own, so going from 21.5 to 22.0 only moves
 * the digits that changed. A touch of blur hides the overlap between the
 * outgoing and incoming glyph.
 */
// `custom` is the signed offset of the latest change. AnimatePresence hands
// the current value to the leaving glyph too, so it always exits opposite to
// the one coming in.
const rollVariants: Variants = {
  // A full transform string rather than `y`, so Motion can hand the roll to
  // the compositor instead of stepping it on the main thread.
  enter: (offset: number) => ({
    opacity: 0,
    transform: `translateY(${offset}px)`,
    filter: offset === 0 ? "blur(0px)" : "blur(2px)",
  }),
  center: { opacity: 1, transform: "translateY(0px)", filter: "blur(0px)" },
  exit: (offset: number) => ({
    opacity: 0,
    transform: `translateY(${-offset}px)`,
    filter: offset === 0 ? "blur(0px)" : "blur(2px)",
  }),
};

function RollingValue({
  text,
  direction,
  reduceMotion,
}: {
  text: string;
  direction: 1 | -1;
  reduceMotion: boolean;
}) {
  const offset = reduceMotion ? 0 : direction * 10;
  return (
    <span
      aria-hidden="true"
      className="relative flex font-medium text-3xl text-zinc-900 tabular-nums tracking-tight dark:text-zinc-100"
    >
      {text.split("").map((char, index) => (
        <span
          className="relative inline-flex overflow-hidden"
          // Position is the identity: the same slot keeps its node.
          // biome-ignore lint/suspicious/noArrayIndexKey: characters are positional.
          key={index}
        >
          <AnimatePresence custom={offset} initial={false} mode="popLayout">
            <motion.span
              animate="center"
              custom={offset}
              exit="exit"
              initial="enter"
              key={char}
              transition={{ duration: 0.16, ease: EASE_OUT }}
              variants={rollVariants}
            >
              {char}
            </motion.span>
          </AnimatePresence>
        </span>
      ))}
    </span>
  );
}

"use client";
// MigBits installation adaptation: scoped cn import; original source is preserved in the ZIP.


/**
 * @author: @dorianbaffier
 * @description: Liquid Slider
 * @version: 1.0.0
 * @date: 2026-10-14
 * @license: MIT
 * @website: https://kokonutui.com
 * @github: https://github.com/kokonut-labs/kokonutui
 */

import {
  type KeyboardEvent,
  type PointerEvent,
  useCallback,
  useEffect,
  useId,
  useRef,
  useState,
} from "react";
import { cn } from "./utils";

const WIDTH = 280;
const HEIGHT = 360;
// The glass is a cylinder seen from a little above: its rim and floor are
// ellipses RY tall, its walls run from LEFT to RIGHT.
const LEFT = 84;
const RIGHT = 196;
const CX = (LEFT + RIGHT) / 2;
const RADIUS = (RIGHT - LEFT) / 2;
const RY = 9;
const RIM_Y = 104;
const FLOOR_Y = 312;
// Where the surface sits when the glass is empty and when it is full.
const EMPTY_Y = FLOOR_Y;
const FULL_Y = RIM_Y + 16;

// The surface is a row of columns that each bob up and down and pull on
// their neighbours: a 1D wave. Heights in px, time in seconds.
const COLUMNS = 34;
const STEP = 1 / 120;
const SPREAD = 2600;
const TENSION = 30;
const DAMPING = 2.4;
// Neighbouring columns drag on each other's speed, which smooths out
// the short, jagged ripples and leaves the long sloshes.
const VISCOSITY = 22;
const MAX_WAVE = 16;
// While dragging, the surface under the finger is pulled towards it this
// hard, and the finger's sideways speed piles the liquid up ahead of it.
const GRAB = 900;
const GRAB_REACH = 2.6;
const GRAB_MAX = 14;
const STIR = 0.55;
// The level chases its target on a spring: fast, but not instant, so a quick
// drag leaves the liquid behind the finger for a moment.
const LEVEL_STIFFNESS = 220;
const LEVEL_DAMPING = 26;
const MAX_BUBBLES = 14;
const REST_EPSILON = 0.02;

interface Bubble {
  x: number;
  y: number;
  r: number;
  speed: number;
  phase: number;
}

function clamp(value: number, min: number, max: number) {
  return Math.min(Math.max(value, min), max);
}

function haptic() {
  if (typeof navigator !== "undefined" && "vibrate" in navigator) {
    navigator.vibrate(4);
  }
}

// How far in front of / behind the centre line the surface ellipse reaches at
// each column, precomputed and rounded so server and browser markup match.
const COLUMN_X: number[] = [];
const DEPTH: number[] = [];
for (let i = 0; i < COLUMNS; i++) {
  const t = i / (COLUMNS - 1);
  const x = LEFT + t * (RIGHT - LEFT);
  COLUMN_X.push(Math.round(x * 100) / 100);
  const u = (x - CX) / RADIUS;
  DEPTH.push(Math.round(RY * Math.sqrt(Math.max(0, 1 - u * u)) * 100) / 100);
}

function levelToY(level: number) {
  return EMPTY_Y - level * (EMPTY_Y - FULL_Y);
}

function f(n: number) {
  return n.toFixed(2);
}

/** The top of the liquid: from the back edge across, then the front back. */
function surfacePath(levelY: number, heights: Float64Array) {
  let d = "";
  for (let i = 0; i < COLUMNS; i++) {
    const y = Math.min(levelY + heights[i] - DEPTH[i], FLOOR_Y);
    d += `${i === 0 ? "M" : "L"}${f(COLUMN_X[i])} ${f(y)}`;
  }
  for (let i = COLUMNS - 1; i >= 0; i--) {
    const y = Math.min(levelY + heights[i] + DEPTH[i], FLOOR_Y + DEPTH[i]);
    d += `L${f(COLUMN_X[i])} ${f(y)}`;
  }
  return `${d}Z`;
}

/** The body: the front edge of the surface, down the wall, along the floor. */
function bodyPath(levelY: number, heights: Float64Array) {
  let d = "";
  for (let i = 0; i < COLUMNS; i++) {
    const y = Math.min(levelY + heights[i] + DEPTH[i], FLOOR_Y + DEPTH[i]);
    d += `${i === 0 ? "M" : "L"}${f(COLUMN_X[i])} ${f(y)}`;
  }
  d += `L${RIGHT} ${FLOOR_Y} A${RADIUS} ${RY} 0 0 1 ${LEFT} ${FLOOR_Y}Z`;
  return d;
}

/** A thin line along the front lip, where light catches the surface. */
function lipPath(levelY: number, heights: Float64Array) {
  let d = "";
  for (let i = 1; i < COLUMNS - 1; i++) {
    const y = Math.min(levelY + heights[i] + DEPTH[i], FLOOR_Y + DEPTH[i]);
    d += `${i === 1 ? "M" : "L"}${f(COLUMN_X[i])} ${f(y)}`;
  }
  return d;
}

/** Surface height (px from the level) at an x, between two columns. */
function heightAt(heights: Float64Array, x: number) {
  const t = clamp((x - LEFT) / (RIGHT - LEFT), 0, 1) * (COLUMNS - 1);
  const i = Math.floor(t);
  const j = Math.min(i + 1, COLUMNS - 1);
  return heights[i] + (heights[j] - heights[i]) * (t - i);
}

const FLAT = new Float64Array(COLUMNS);

export interface LiquidSliderProps {
  value?: number;
  defaultValue?: number;
  onValueChange?: (value: number) => void;
  min?: number;
  max?: number;
  step?: number;
  /** Shown after the number. */
  unit?: string;
  label?: string;
  /** Formats the readout and `aria-valuetext`. */
  formatValue?: (value: number) => string;
  className?: string;
}

const defaultFormat = (value: number) => value.toLocaleString("en-US");

export default function LiquidSlider({
  value: valueProp,
  defaultValue = 1250,
  onValueChange,
  min = 0,
  max = 2000,
  step = 50,
  unit = "ml",
  label = "Water today",
  formatValue = defaultFormat,
  className,
}: LiquidSliderProps) {
  const [internal, setInternal] = useState(defaultValue);
  const value = clamp(valueProp ?? internal, min, max);
  const [dragging, setDragging] = useState(false);
  const labelId = useId();

  const surfaceRef = useRef<SVGPathElement>(null);
  const bodyRef = useRef<SVGPathElement>(null);
  const lipRef = useRef<SVGPathElement>(null);
  const bubblesRef = useRef<(SVGCircleElement | null)[]>([]);
  const svgRef = useRef<SVGSVGElement>(null);

  const fraction = (max - min > 0 ? (value - min) / (max - min) : 0) || 0;
  const initialY = levelToY(fraction);

  const sim = useRef({
    heights: new Float64Array(COLUMNS),
    speeds: new Float64Array(COLUMNS),
    accels: new Float64Array(COLUMNS),
    level: fraction,
    levelSpeed: 0,
    target: fraction,
    bubbles: [] as Bubble[],
    raf: 0,
    last: 0,
    carry: 0,
    // Pointer, while held: where it is, in drawing units, and its sideways
    // speed.
    held: false,
    pointerId: -1,
    px: 0,
    py: 0,
    pvx: 0,
    lastPx: 0,
    lastT: 0,
    reduceMotion: false,
    seed: 1,
  });

  // Handlers outlive the render they came from; read the props here.
  const latest = useRef({ value, min, max, step, onValueChange });
  latest.current = { value, min, max, step, onValueChange };

  const commit = useCallback(
    (next: number) => {
      const { min: lo, max: hi, step: inc } = latest.current;
      const snapped = clamp(
        Number((Math.round((next - lo) / inc) * inc + lo).toFixed(10)),
        lo,
        hi
      );
      if (snapped === latest.current.value) {
        return;
      }
      // A light tick each time the level crosses a quarter.
      const quarter = (hi - lo) / 4;
      if (
        Math.floor((snapped - lo) / quarter) !==
        Math.floor((latest.current.value - lo) / quarter)
      ) {
        haptic();
      }
      latest.current.value = snapped;
      if (valueProp === undefined) {
        setInternal(snapped);
      }
      latest.current.onValueChange?.(snapped);
    },
    [valueProp]
  );

  const random = useCallback(() => {
    // Deterministic, so bubbles never depend on Math.random during render.
    const s = sim.current;
    s.seed = (s.seed * 16_807) % 2_147_483_647;
    return s.seed / 2_147_483_647;
  }, []);

  const draw = useCallback(() => {
    const s = sim.current;
    const y = levelToY(s.level);
    surfaceRef.current?.setAttribute("d", surfacePath(y, s.heights));
    bodyRef.current?.setAttribute("d", bodyPath(y, s.heights));
    lipRef.current?.setAttribute("d", lipPath(y, s.heights));
    for (let i = 0; i < MAX_BUBBLES; i++) {
      const el = bubblesRef.current[i];
      const b = s.bubbles[i];
      if (!el) {
        continue;
      }
      if (b) {
        const wobble = Math.sin(b.phase) * 1.6;
        el.setAttribute("cx", f(b.x + wobble));
        el.setAttribute("cy", f(b.y));
        el.setAttribute("r", f(b.r));
        el.style.opacity = "1";
      } else {
        el.style.opacity = "0";
      }
    }
  }, []);

  // The level rides a spring towards its target. When it rises fast, the
  // pour drags bubbles in from the floor.
  const stepLevel = useCallback(() => {
    const s = sim.current;
    const force =
      (s.target - s.level) * LEVEL_STIFFNESS - s.levelSpeed * LEVEL_DAMPING;
    s.levelSpeed += force * STEP;
    s.level += s.levelSpeed * STEP;
    if (
      s.levelSpeed > 0.5 &&
      s.bubbles.length < MAX_BUBBLES &&
      random() < s.levelSpeed * 0.05
    ) {
      s.bubbles.push({
        x: LEFT + 10 + random() * (RIGHT - LEFT - 20),
        y: FLOOR_Y + 2,
        r: 1.2 + random() * 2,
        speed: 40 + random() * 50,
        phase: random() * Math.PI * 2,
      });
    }
  }, [random]);

  // One step of the wave: each column accelerates towards its neighbours'
  // average and back to rest, then the volume is re-levelled so the waves
  // only move liquid around.
  const stepWaves = useCallback(() => {
    const s = sim.current;
    const { heights: h, speeds: v, accels: a } = s;
    const levelY = levelToY(s.level);
    let mean = 0;
    for (let i = 0; i < COLUMNS; i++) {
      const l = i === 0 ? 0 : i - 1;
      const r = i === COLUMNS - 1 ? i : i + 1;
      let accel =
        SPREAD * (h[l] + h[r] - 2 * h[i]) +
        VISCOSITY * (v[l] + v[r] - 2 * v[i]) -
        TENSION * h[i] -
        DAMPING * v[i];
      if (s.held) {
        const reach = (COLUMN_X[i] - s.px) / ((RIGHT - LEFT) / COLUMNS);
        const weight = Math.exp(-(reach * reach) / (GRAB_REACH * GRAB_REACH));
        const pull = clamp(s.py - (levelY + h[i]), -GRAB_MAX, GRAB_MAX);
        accel += GRAB * pull * weight * 0.05;
        accel -= STIR * s.pvx * ((i - (COLUMNS - 1) / 2) / COLUMNS) * 60;
      }
      a[i] = accel;
    }
    for (let i = 0; i < COLUMNS; i++) {
      v[i] += a[i] * STEP;
      h[i] = clamp(h[i] + v[i] * STEP, -MAX_WAVE, MAX_WAVE);
      mean += h[i];
    }
    mean /= COLUMNS;
    let energy = 0;
    for (let i = 0; i < COLUMNS; i++) {
      h[i] -= mean;
      energy += Math.abs(h[i]) + Math.abs(v[i]) * STEP;
    }
    return energy / COLUMNS;
  }, []);

  // Bubbles rise with a wobble and pop at the surface, leaving a ripple.
  const stepBubbles = useCallback(() => {
    const s = sim.current;
    const levelY = levelToY(s.level);
    for (let i = s.bubbles.length - 1; i >= 0; i--) {
      const b = s.bubbles[i];
      b.y -= b.speed * STEP;
      b.phase += STEP * 9;
      if (b.y <= levelY + heightAt(s.heights, b.x) + 1) {
        const col = Math.round(((b.x - LEFT) / (RIGHT - LEFT)) * (COLUMNS - 1));
        s.speeds[clamp(col, 0, COLUMNS - 1)] -= 30 * b.r;
        s.bubbles.splice(i, 1);
      }
    }
  }, []);

  const tick = useCallback(
    (now: number) => {
      const s = sim.current;
      s.raf = 0;
      const elapsed = s.last ? Math.min((now - s.last) / 1000, 0.05) : STEP;
      s.last = now;
      s.carry += elapsed;
      let energy = 0;
      while (s.carry >= STEP) {
        stepLevel();
        energy = stepWaves();
        stepBubbles();
        s.carry -= STEP;
      }
      // The sideways speed fades when the pointer stops moving.
      s.pvx *= 0.85;
      draw();
      const settled =
        !s.held &&
        energy < REST_EPSILON &&
        Math.abs(s.target - s.level) < 0.0005 &&
        Math.abs(s.levelSpeed) < 0.001 &&
        s.bubbles.length === 0;
      if (settled) {
        s.level = s.target;
        s.heights.fill(0);
        s.speeds.fill(0);
        s.last = 0;
        draw();
        return;
      }
      s.raf = requestAnimationFrame(tick);
    },
    [draw, stepBubbles, stepLevel, stepWaves]
  );

  const wake = useCallback(() => {
    const s = sim.current;
    if (s.reduceMotion) {
      s.level = s.target;
      s.levelSpeed = 0;
      s.heights.fill(0);
      s.speeds.fill(0);
      s.bubbles.length = 0;
      draw();
      return;
    }
    if (!s.raf) {
      s.raf = requestAnimationFrame(tick);
    }
  }, [draw, tick]);

  useEffect(() => {
    const s = sim.current;
    const query = window.matchMedia("(prefers-reduced-motion: reduce)");
    s.reduceMotion = query.matches;
    const onChange = () => {
      s.reduceMotion = query.matches;
    };
    query.addEventListener("change", onChange);
    // Pause while the tab is hidden; the loop picks up again on return.
    const onVisibility = () => {
      if (document.hidden && s.raf) {
        cancelAnimationFrame(s.raf);
        s.raf = 0;
        s.last = 0;
      } else if (!document.hidden) {
        wake();
      }
    };
    document.addEventListener("visibilitychange", onVisibility);
    return () => {
      query.removeEventListener("change", onChange);
      document.removeEventListener("visibilitychange", onVisibility);
      cancelAnimationFrame(s.raf);
      s.raf = 0;
    };
  }, [wake]);

  // A value set from outside (a controlled prop, or a keypress) moves the
  // target; the liquid follows on its own.
  useEffect(() => {
    const s = sim.current;
    if (s.held) {
      return;
    }
    if (Math.abs(s.target - fraction) > 1e-6) {
      s.target = fraction;
      wake();
    }
  }, [fraction, wake]);

  const localPoint = (event: PointerEvent) => {
    const rect = svgRef.current?.getBoundingClientRect();
    if (!rect) {
      return { x: 0, y: 0 };
    }
    return {
      x: ((event.clientX - rect.left) / rect.width) * WIDTH,
      y: ((event.clientY - rect.top) / rect.height) * HEIGHT,
    };
  };

  const follow = (event: PointerEvent) => {
    const s = sim.current;
    const point = localPoint(event);
    const now = event.timeStamp;
    if (s.lastT && now > s.lastT) {
      const vx = ((point.x - s.lastPx) / (now - s.lastT)) * 1000;
      s.pvx = s.pvx * 0.6 + clamp(vx, -900, 900) * 0.4;
    }
    s.lastPx = point.x;
    s.lastT = now;
    s.px = clamp(point.x, LEFT, RIGHT);
    s.py = clamp(point.y, FULL_Y, EMPTY_Y);
    const raw = clamp((EMPTY_Y - point.y) / (EMPTY_Y - FULL_Y), 0, 1);
    s.target = raw;
    const { min: lo, max: hi } = latest.current;
    commit(lo + raw * (hi - lo));
    wake();
  };

  const handlePointerDown = (event: PointerEvent<SVGSVGElement>) => {
    if (event.pointerType === "mouse" && event.button !== 0) {
      return;
    }
    const s = sim.current;
    // A second finger mid-drag is ignored rather than jumping the level.
    if (s.held) {
      return;
    }
    event.preventDefault();
    // Focus without scrolling, so the keyboard picks up where the hand left.
    (event.currentTarget.parentElement as HTMLElement | null)?.focus({
      preventScroll: true,
    });
    event.currentTarget.setPointerCapture(event.pointerId);
    s.held = true;
    s.pointerId = event.pointerId;
    s.lastT = 0;
    s.pvx = 0;
    setDragging(true);
    follow(event);
  };

  const handlePointerMove = (event: PointerEvent<SVGSVGElement>) => {
    const s = sim.current;
    if (s.held && s.pointerId === event.pointerId) {
      follow(event);
    }
  };

  const handlePointerUp = (event: PointerEvent<SVGSVGElement>) => {
    const s = sim.current;
    if (!s.held || s.pointerId !== event.pointerId) {
      return;
    }
    s.held = false;
    setDragging(false);
    // Settle on the step the readout shows.
    const { value: v, min: lo, max: hi } = latest.current;
    s.target = hi - lo > 0 ? (v - lo) / (hi - lo) : 0;
    wake();
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const { min: lo, max: hi, step: inc } = latest.current;
    const big = Math.max(inc, (hi - lo) / 10);
    const moves: Record<string, number> = {
      ArrowUp: value + inc,
      ArrowRight: value + inc,
      ArrowDown: value - inc,
      ArrowLeft: value - inc,
      PageUp: value + big,
      PageDown: value - big,
      Home: lo,
      End: hi,
    };
    const next = Object.hasOwn(moves, event.key) ? moves[event.key] : null;
    if (next === null) {
      return;
    }
    event.preventDefault();
    commit(next);
    // A drop in the middle, so the key gets a ripple too.
    const s = sim.current;
    if (!s.reduceMotion) {
      s.speeds[Math.floor(COLUMNS / 2)] += next > value ? -90 : 90;
      wake();
    }
  };

  const ticks = [0, 0.25, 0.5, 0.75, 1];
  const initialSurface = surfacePath(initialY, FLAT);
  const initialBody = bodyPath(initialY, FLAT);
  const initialLip = lipPath(initialY, FLAT);

  return (
    <div
      aria-labelledby={labelId}
      aria-orientation="vertical"
      aria-valuemax={max}
      aria-valuemin={min}
      aria-valuenow={value}
      aria-valuetext={`${formatValue(value)} ${unit}`.trim()}
      className={cn(
        "relative select-none overflow-hidden rounded-3xl border border-zinc-200 bg-white text-zinc-900 outline-none focus-visible:outline-2 focus-visible:outline-zinc-400 focus-visible:outline-offset-2 dark:border-zinc-800 dark:bg-zinc-950 dark:text-zinc-100",
        className
      )}
      onKeyDown={handleKeyDown}
      role="slider"
      style={{ width: WIDTH, height: HEIGHT }}
      tabIndex={0}
    >
      <div className="pointer-events-none absolute inset-x-0 top-0 p-6">
        <p className="text-sm text-zinc-500" id={labelId}>
          {label}
        </p>
        <p className="mt-0.5 font-medium text-2xl tabular-nums tracking-tight">
          {formatValue(value)}
          <span className="ml-1 text-base text-zinc-400">{unit}</span>
        </p>
      </div>

      <svg
        aria-hidden="true"
        className={cn(
          "absolute inset-0 touch-none",
          dragging ? "cursor-grabbing" : "cursor-grab"
        )}
        height={HEIGHT}
        onLostPointerCapture={handlePointerUp}
        onPointerCancel={handlePointerUp}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        ref={svgRef}
        viewBox={`0 0 ${WIDTH} ${HEIGHT}`}
        width={WIDTH}
      >
        <defs>
          <clipPath id={`${labelId}-glass`}>
            <path
              d={`M${LEFT} ${RIM_Y} L${RIGHT} ${RIM_Y} L${RIGHT} ${FLOOR_Y} A${RADIUS} ${RY} 0 0 1 ${LEFT} ${FLOOR_Y} Z`}
            />
          </clipPath>
        </defs>

        {/* The back of the glass. */}
        <path
          className="fill-zinc-50 dark:fill-zinc-900/60"
          d={`M${LEFT} ${RIM_Y} A${RADIUS} ${RY} 0 0 1 ${RIGHT} ${RIM_Y} L${RIGHT} ${FLOOR_Y} A${RADIUS} ${RY} 0 0 1 ${LEFT} ${FLOOR_Y} Z`}
        />
        <path
          className="fill-none stroke-zinc-200 dark:stroke-zinc-800"
          d={`M${LEFT} ${FLOOR_Y} A${RADIUS} ${RY} 0 0 1 ${RIGHT} ${FLOOR_Y}`}
          strokeWidth={1}
        />

        <g clipPath={`url(#${labelId}-glass)`}>
          <path className="fill-sky-500" d={initialBody} ref={bodyRef} />
          {Array.from({ length: MAX_BUBBLES }, (_, i) => (
            <circle
              className="fill-white/25 stroke-white/70"
              cx={CX}
              cy={FLOOR_Y}
              // biome-ignore lint/suspicious/noArrayIndexKey: a fixed pool of circles reused by index
              key={i}
              r={1}
              ref={(el) => {
                bubblesRef.current[i] = el;
              }}
              strokeWidth={0.75}
              style={{ opacity: 0 }}
            />
          ))}
          <path
            className="fill-sky-300 dark:fill-sky-400"
            d={initialSurface}
            ref={surfaceRef}
          />
          <path
            className="fill-none stroke-white/60"
            d={initialLip}
            ref={lipRef}
            strokeLinecap="round"
            strokeWidth={1}
          />
        </g>

        {/* Graduations, printed on the front of the glass. */}
        {ticks.map((t) => {
          const y = Math.round(levelToY(t) + RY * 0.55);
          const tickValue = min + t * (max - min);
          return (
            <g key={t}>
              <line
                className="stroke-zinc-900/25 dark:stroke-white/30"
                strokeWidth={1}
                x1={RIGHT - 14}
                x2={RIGHT - 4}
                y1={y}
                y2={y}
              />
              <text
                className="fill-zinc-400 text-[10px] tabular-nums dark:fill-zinc-500"
                dominantBaseline="middle"
                x={RIGHT + 8}
                y={y}
              >
                {formatValue(tickValue)}
              </text>
            </g>
          );
        })}

        {/* The glass itself: rim, walls and the front of the floor. */}
        <ellipse
          className="fill-none stroke-zinc-300 dark:stroke-zinc-700"
          cx={CX}
          cy={RIM_Y}
          rx={RADIUS}
          ry={RY}
          strokeWidth={1.5}
        />
        <path
          className="fill-none stroke-zinc-300 dark:stroke-zinc-700"
          d={`M${LEFT} ${RIM_Y} L${LEFT} ${FLOOR_Y} A${RADIUS} ${RY} 0 0 0 ${RIGHT} ${FLOOR_Y} L${RIGHT} ${RIM_Y}`}
          strokeWidth={1.5}
        />
        {/* A strip of reflection down the left wall. */}
        <line
          className="stroke-white/50 dark:stroke-white/10"
          strokeLinecap="round"
          strokeWidth={3}
          x1={LEFT + 9}
          x2={LEFT + 9}
          y1={RIM_Y + 22}
          y2={FLOOR_Y - 14}
        />
      </svg>
    </div>
  );
}

